package com.greenocean.backend.listener.planning;
import com.greenocean.backend.listener.live.LiveSupportService;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.scheduling.annotation.Scheduled;import java.time.*;import java.util.*;import static com.greenocean.backend.listener.planning.ListenerSupportPolicy.*;
@Service @Transactional public class ListenerSupportMaintenance {
 private final ListenerSupportPolicy p;private final LiveSupportService live;
 public ListenerSupportMaintenance(ListenerSupportPolicy p,LiveSupportService live){this.p=p;this.live=live;}
 @Scheduled(fixedDelayString="${greenocean.listener-support.maintenance-ms:10000}") public void sweep(){run();}
 public void run(){p.liveLock();live.reconcile();var limits=p.limits();
  for(var r:p.db.queryForList("SELECT r.id,r.conversation_id,r.planned_ends_at FROM live_support_requests r WHERE r.status='ACTIVE' AND r.planned_ends_at>listener_support_now() AND r.planned_ends_at<=listener_support_now()+(?*INTERVAL '1 second') AND NOT EXISTS(SELECT 1 FROM listener_session_warning_notices n WHERE n.session_id=r.id AND n.deadline=r.planned_ends_at AND n.kind=CASE WHEN r.planned_ends_at<=listener_support_now()+(?*INTERVAL '1 second') THEN 'ENDING_FINAL' ELSE 'ENDING_EARLY' END) ORDER BY r.planned_ends_at,r.id LIMIT 100",limits.warningEarlySeconds(),limits.warningFinalSeconds())){
   Instant deadline=instant(r.get("planned_ends_at"));boolean last=!deadline.isAfter(p.now().plusSeconds(limits.warningFinalSeconds()));String kind=last?"ENDING_FINAL":"ENDING_EARLY";
   if(p.db.update("INSERT INTO listener_session_warning_notices(session_id,kind,deadline) VALUES(?,?,?) ON CONFLICT DO NOTHING",r.get("id"),kind,date(deadline))==1){int warning=last?limits.warningFinalSeconds():limits.warningEarlySeconds();String body="At most "+warning+" seconds remain before the authorized session deadline. Sending closes at the server deadline. / حداکثر "+warning+" ثانیه تا پایان مجاز جلسه باقی مانده است؛ ارسال در مهلت سرور بسته می‌شود.";p.db.update("INSERT INTO messages(id,conversation_id,message_kind,body) SELECT ?,conversation_id,'SYSTEM',? FROM live_support_requests WHERE id=? AND status='ACTIVE' AND planned_ends_at>listener_support_now()",UUID.randomUUID(),body,r.get("id"));}
  }
  if(p.booking())for(var n:p.db.queryForList("SELECT b.id,x.user_id,x.kind FROM listener_bookings b CROSS JOIN listener_support_policy policy CROSS JOIN LATERAL(VALUES(b.member_id,CASE WHEN b.starts_at<=listener_support_now()+(policy.checkin_seconds*INTERVAL '1 second') THEN 'BOOKING_CHECKIN_OPEN' ELSE 'BOOKING_APPROACHING' END),(b.listener_id,CASE WHEN b.starts_at>listener_support_now()+(policy.checkin_seconds*INTERVAL '1 second') THEN 'BOOKING_APPROACHING' WHEN b.status='CHECKED_IN' THEN 'BOOKING_MEMBER_CHECKED_IN' END))x(user_id,kind) JOIN user_preferences pref ON pref.user_id=x.user_id WHERE b.reminders AND pref.notify_messages AND x.kind IS NOT NULL AND b.status IN('CONFIRMED','CHECKED_IN') AND b.starts_at<=listener_support_now()+(policy.lead_seconds*INTERVAL '1 second') AND b.starts_at>listener_support_now()-(policy.grace_seconds*INTERVAL '1 second') AND NOT EXISTS(SELECT 1 FROM listener_support_notices sent WHERE sent.user_id=x.user_id AND sent.entity_id=b.id AND sent.kind=x.kind) ORDER BY b.starts_at,b.id,x.user_id LIMIT 100"))p.notice((UUID)n.get("user_id"),(UUID)n.get("id"),(String)n.get("kind"),true);
  for(var n:p.db.queryForList("SELECT b.id,x.user_id,CASE WHEN b.reason_code='RESCHEDULED' THEN 'BOOKING_CHANGED' ELSE b.status END AS kind FROM listener_bookings b CROSS JOIN LATERAL(VALUES(b.member_id),(b.listener_id))x(user_id) JOIN user_preferences pref ON pref.user_id=x.user_id CROSS JOIN listener_support_policy policy WHERE b.reminders AND pref.notify_messages AND b.status IN('CANCELLED_BY_MEMBER','CANCELLED_BY_LISTENER','CANCELLED_BY_SERVICE','MEMBER_NO_SHOW','LISTENER_NO_SHOW','EXPIRED') AND EXISTS(SELECT 1 FROM listener_booking_events e WHERE e.booking_id=b.id AND e.created_at>listener_support_now()-(policy.queue_seconds*INTERVAL '1 second')) AND NOT EXISTS(SELECT 1 FROM listener_support_notices sent WHERE sent.user_id=x.user_id AND sent.entity_id=b.id AND sent.kind=CASE WHEN b.reason_code='RESCHEDULED' THEN 'BOOKING_CHANGED' ELSE b.status END) ORDER BY b.starts_at,b.id,x.user_id LIMIT 100"))p.notice((UUID)n.get("user_id"),(UUID)n.get("id"),(String)n.get("kind"),true);
  p.db.update("INSERT INTO listener_support_worker_state(name,last_success_at) VALUES('planning-maintenance',listener_support_now()) ON CONFLICT(name) DO UPDATE SET last_success_at=EXCLUDED.last_success_at");
 }
}
